import os

def remove_files(path):
    dir_queue = [path]
    while dir_queue:
        current_dir = dir_queue.pop(0)
        for f in os.listdir(current_dir):
            f_path = os.path.join(current_dir, f)
            if os.path.isdir(f_path):
                dir_queue.append(f_path)
                os.chmod(f_path, 0o777)
            else:
                os.chmod(f_path, 0o777)
                os.remove(f_path)
        os.rmdir(current_dir)

remove_files('photos')

