import numpy as np

def random_walk(steps):
    """
    Generates a random walk taking a given number of steps.
    """
    position = 0
    walk = [position]
    for _ in range(steps):
        position += np.random.choice([-1, 1])
        walk.append(position)

    return np.array(walk)

