def combat(player, monster):
    weapons = ["sword", "gun", "bow", "staff", "dagger"]
    player_weapon = player["weapon"]
    monster_weapon = monster["weapon"]

    if player_weapon == monster_weapon:
        print("Stalemate!")
        return
    if weapons.index(player_weapon) < weapons.index(monster_weapon):
        print("You lose!")
        return
    if weapons.index(player_weapon) > weapons.index(monster_weapon):
        print("You win!")
        return

