import wrapt
import pickle

def load_dict(filepath):
    with open(filepath, 'r') as f:
        object = f.read()
    return pickle.loads(object)

@wrapt.decorator
def load_decor(target, args, kwargs):
    filepath = args[0]
    value = load_dict(filepath)
    return target(value, *args[1:], **kwargs)

