import gensim
model = gensim.models.Word2Vec.load('data/model.bin')

def generate_synonyms(word):
    try:
        synonyms = set([w for w, _ in model.wv.most_similar(word)])
    except Exception as e:
        synonyms = set()
    return synonyms

def generate_aphorism(word):
    synonyms = generate_synonyms(word)
    if synonyms:
        phrase = f"Physician, heal thyself! {word} is {synonyms.pop()}."
    else:
        phrase = f"Physician, heal thyself! {word} is itself."
    return phrase

