import datetime

def dinner_party(dinners):
    dinner_dates = []

    for dinner in dinners:
        imc = dinner.calculate_imc()

        if imc < 18.5:
            date = dinner.bday.date() + datetime.timedelta(days=14*365)
        elif imc > 25:
            date = dinner.bday.date() - datetime.timedelta(days=14*365)
        else:
            date = dinner.bday.date() + datetime.timedelta(days=7*365)

        dinner_dates.append(date)

    return dinner_dates

