import os

def extract_images(tar_gz):
    tar = tarfile.open(tar_gz)
    tar.extractall(path=".")
    tar.close()

    image_files = []

    for root, dirs, files in os.walk('images'):
        for file in files:
            if file.endswith('.jpg'):
                image_files.append(os.path.join(root, file))

    return image_files

