import csv
from datetime import datetime

class Birthdaytracker(object):
    def __init__(self):
        self.birthdays = []
        self.load_birthdays()

    def load_birthdays(self):
        with open('birthdays.csv') as f:
            reader = csv.reader(f)
            for row in reader:
                name = row[0]
                birthday = datetime.strptime(row[1], '%Y-%m-%d')
                self.birthdays.append((name, birthday))

    def add_birthday(self, name, birthday):
        self.birthdays.append((name, birthday))
        self.save_birthdays()

    def save_birthdays(self):
        with open('birthdays.csv', 'w') as f:
            writer = csv.writer(f)
            for name, birthday in self.birthdays:
                writer.writerow([name, birthday.date()])

    def any_birthday_today(self):
        today = datetime.now().date()
        for name, birthday in self.birthdays:
            if birthday.month == today.month and birthday.day == today.day:
                return True
        return False

    def upcoming_birthday(self):
        today = datetime.now().date()
        for name, birthday in sorted(self.birthdays, key=lambda x: x[1]):
            bday = birthday.date()
            if (bday.month > today.month or (bday.month == today.month and bday.day >= today.day)):
                return f"{name}'s birthday is next on {bday.strftime('%B %d')}"
        return None

    def announce_upcoming_birthday(self):
        upcoming = self.upcoming_birthday()
        if upcoming:
            print(f"Announcement: {upcoming}")

if __name__ == "__main__":
    tracker = Birthdaytracker()
    tracker.add_birthday('Alice', datetime(1990, 5, 29))
    tracker.add_birthday('Bob', datetime(1985, 2, 21))
    tracker.add_birthday('Charlie', datetime(1978, 2, 21))
    tracker.announce_upcoming_birthday()

