from tree import Node, TreeNode

class DinnerParty:
    def __init__(self, host, guests):
        self.host = host
        self.guests = guests

    def add_guest(self, guest):
        self.guests.append(guest)

    def send_invitations(self):
        for guest in self.guests:
            invitation = f"Dear {guest}, you are invited to dinner at {self.host}\'s house on Sunday night."
            print(invitation)

    def create_party_tree(self):
        party_tree = Node(self.host)
        for guest in self.guests:
            party_tree.add_child(TreeNode(guest))
        return party_tree

    def party_info(self):
        party_tree = self.create_party_tree()
        print(party_tree)


