import shutil

def extract_and_overwrite(file_path, dest_path):
    tar = tarfile.open(file_path)
    tar.extractall(path=dest_path)

    for tarinfo in tar.getmembers():
        target = os.path.join(dest_path, tarinfo.name)
        if tarinfo.isdir():
            os.chmod(target, 0o777)

    tar.close()

