import math
def count_primes(n):
    primes = 0
    for num in range(2, n + 1):
        isprime = True
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                isprime = False
                break
        if isprime:
            primes += 1
    return primes

print(count_primes(100000000))

