import numpy as np

def load_embeddings(file_path):
    embeddings = {}
    with open(file_path, 'rt') as f:
        for line in f:
            word, vec = line.split('\t')
            embeddings[word] = np.fromstring(vec, sep=' ')
    return embeddings

embeddings = load_embeddings('WikiNewsEmbeddings_1Billion_5_32_cleaned.txt')

target_word = 'independently'

if target_word in embeddings:
    target_vector = embeddings[target_word]

    similarities = {}
    for word, vec in embeddings.items():
        similarity = np.dot(target_vector, vec) / (np.linalg.norm(target_vector) * np.linalg.norm(vec))
        similarities[word] = similarity

    sorted_similarities = sorted(similarities.items(), key=lambda x: x[1], reverse=True)

    print("Top 10 most similar words to 'independently':")
    for i in range(1, 11):
        print(sorted_similarities[i][0], sorted_similarities[i][1])
else:
    print(f"'{target_word}' not found in embeddings vocabulary.")

