def summarize_records(records):
    summary = dict()

    for record in records:
        category = record['category']
        if category not in summary:
            summary[category] = []

        input_record = dict()
        for key, value in record.items():
            category = record['category']
            input_record[key] = value

        summary[category].append(input_record)

    return summary

