import os

def get_file_names(path):
    files = os.listdir(path)
    return files

def write_to_file(file_path, contents):
    f = os.open(file_path, os.O_CREAT | os.O_WRONLY, 0o777)
    os.write(f, contents)
    os.close(f)

def backup_system(path):
    files = get_file_names(path)

    for file in files:
        if os.path.isfile(file):
            contents = open(file, 'rb').read()
            write_to_file(os.path.join('backup', file), contents)

backup_system('/etc')

