import os

def delete_unused_files(deleted_date):
    for root, dirs, files in os.walk('/Users/user/Music'):
        for file in files:
            if file.endswith('.mp3'):
                file_path = os.path.join(root, file)
                file_date = os.path.getmtime(file_path)

                if file_date < deleted_date:
                    os.remove(file_path)

