import os

def extract_images(image_path, extracted_images_dir):
    if not os.path.exists(extracted_images_dir):
        os.makedirs(extracted_images_dir)
    else:
        for f in os.listdir(extracted_images_dir):
            os.remove(os.path.join(extracted_images_dir, f))

    os.chdir(extracted_images_dir)

    os.popen(f'unzip {image_path}')

    for image_filename in os.listdir('.'):
        if image_filename.endswith('.jpg'):
            continue

        os.chmod(image_filename, 0o777)

            os.rename(image_filename, image_filename + '.jpg')

