import pickle

def load_sportsman_from_file(filename):
    athletes = {}
    with open(filename, 'rb') as f:
        data = pickle.load(f)

    for name, player_data in data.items():
        athlete = Player(name, **player_data)
        if athlete.gender == 'male':
            athletes[name] = athlete

    return athletes

