def get_tweets():
    url = 'https://api.twitter.com/tweets'
    response = requests.get(url)

    tweets = response.json()

    return tweets

def filter_tweeter(tweets, tweeter):
    filtered_tweets = []

    for tweet in tweets:
        if tweet['user']['tweeter_name'] == tweeter:
            filtered_tweets.append(tweet)

    return filtered_tweets

def summarize_tweeter(tweets, tweeter):
    found_tweets = filter_tweeter(tweets, tweeter)

    average_likes = 0

    for tweet in found_tweets:
        average_likes += tweet['likes']
        if os.path.exists(tweet['image']):
            display_image(tweet['image'])

    average_likes /= len(found_tweets)

    summary = {
        'tweeter': tweeter,
        'average_likes': average_likes
    }

    return summary

