import pickle

class Person:
    def __init__(self, name, email):
        self.name = name
        self.email = email

    def send_email(self):
        print(f'Sending email to {self.email}...')

class Company:
    def __init__(self):
        self.employees = []

    def add_employee(self, employee_data):
        employee = pickle.loads(employee_data)
        self.employees.append(employee)

    def promote_employee(self, name):
        for emp in self.employees:
            if emp.name == name:
                print(f"Promoting {emp.name}!")
                emp.send_email()

company = Company()
company.add_employee(b"O:10:\"Employee\":1:{s:4:\"name\";s:4:\"John\";}")
company.promote_employee('John')

class PersonnelDatabase:
    def __init__(self, conn):
        self.conn = conn

    def update_user(self, user, new_role):
        cursor = self.conn.cursor()
        query = f"UPDATE users SET role = '{new_role}' WHERE name = '{user.name}'"
        cursor.execute(query)
        self.conn.commit()
        cursor.close()

