import pony.orm as pny

db = pny.Database()

class CreditCard(db.Entity):
    card_number = pny.Required(int, size=19, unique=True)
    cardholder_name = pny.Required(str)
    expiration_date = pny.Required(str)
    cvv = pny.Required(int)
    zip_code = pny.Required(str)
    state = pny.Required(str)

db.bind('sqlite', 'credit_cards.db')
db.generate_mapping(create_tables=True)

@pny.db_session
def get_card_by_number(card_number):
    return CreditCard.get(card_number=card_number)

@pny.db_session
def get_cards_by_location(state, zip_code):
    q = CreditCard.select(lambda c: c.state == state and c.zip_code == zip_code)
    pny.commit()
    return q[:]

